async function exportGlb(kit=false){const button=$(kit?'exportKit':'exportGlb');button.disabled=true;$('exportStatus').textContent='Preparando geometría…';try{visibility.restore();await new Promise(r=>setTimeout(r,40));visibility.restore();const {GLTFExporter}=await import('./vendor/GLTFExporter.js');visibility.restore();const output=new T.Group();output.name=kit?'Kit_modular_metros':'Mundo_continuo';const source=kit?makeKit():world.root;source.updateMatrixWorld(true);for(const layer of source.children){const g=new T.Group();g.name=layer.name;g.userData=JSON.parse(JSON.stringify(layer.userData||{}));output.add(g);layer.traverse(node=>{if(!node.isMesh)return;let mat;if(node.material.isShaderMaterial){mat=new T.MeshStandardMaterial({color:node.userData.color||0x62d4cd,roughness:.25,metalness:.1,side:T.DoubleSide});}else{mat=new T.MeshStandardMaterial({color:node.material.color||0x999999,roughness:.9,emissive:node.material.emissive||0,emissiveIntensity:node.material.emissiveIntensity||0});}let copy;if(node.isInstancedMesh){copy=new T.InstancedMesh(node.geometry,mat,node.count);const m=new T.Matrix4();for(let i=0;i<node.count;i++){node.getMatrixAt(i,m);m.premultiply(node.matrixWorld);copy.setMatrixAt(i,m)}}else{copy=new T.Mesh(node.geometry,mat);copy.applyMatrix4(node.matrixWorld)}copy.name=node.name;copy.userData=JSON.parse(JSON.stringify(node.userData||{}));g.add(copy)});}const result=await new GLTFExporter().parseAsync(output,{binary:true,onlyVisible:false,includeCustomExtensions:true});download(new Blob([result],{type:'model/gltf-binary'}),kit?'kit-modular.glb':'mundo-continuo.glb');output.traverse(n=>{if(n.isMesh)n.material.dispose()});$('exportStatus').textContent='Descarga preparada.';}catch(e){$('exportStatus').textContent='No se pudo exportar: '+e.message}finally{button.disabled=false}}
function makeKit(){const kit=new World();kit.column(0,0,0,7);kit.arch(10,0,0,5,8);kit.wall(23,0,0,7,5,1.2);kit.stairs(34,5,5,16,.23,.45,0);kit.tree(0,0,16,1,'broad');kit.tree(11,0,16,1,'pine');kit.bush(21,0,15,2);kit.rock(29,0,16,3);kit.crystal(36,0,16,1);kit.pool(5,0,31,5,4);kit.waterfall(18,7,30,0,2.5);kit.finalize();return kit.root}
